import{_ as i,o as a,c as o,a2 as t}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Autonomous Driving System Version Release Plan Roadmap","description":"","frontmatter":{},"headers":[],"relativePath":"roadmap/2025.md","filePath":"roadmap/2025.md","lastUpdated":1787216633000}'),n={name:"roadmap/2025.md"};function r(l,e,s,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="autonomous-driving-system-version-release-plan-roadmap" tabindex="-1">Autonomous Driving System Version Release Plan Roadmap <a class="header-anchor" href="#autonomous-driving-system-version-release-plan-roadmap" aria-label="Permalink to &quot;Autonomous Driving System Version Release Plan Roadmap&quot;">​</a></h1><h2 id="wheel-os-version-release-plan" tabindex="-1">Wheel.OS Version Release Plan <a class="header-anchor" href="#wheel-os-version-release-plan" aria-label="Permalink to &quot;Wheel.OS Version Release Plan&quot;">​</a></h2><h3 id="version-12-31" tabindex="-1">Version 12.31 <a class="header-anchor" href="#version-12-31" aria-label="Permalink to &quot;Version 12.31&quot;">​</a></h3><h4 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h4><ul><li><strong>Core Middleware</strong>: Support for core functionality modules and stability optimizations.</li><li><strong>Common_msgs Message Interface</strong>: Provide standardized message interfaces to support efficient communication between modules.</li><li><strong>Drivers Sensor Driver</strong>: Enhance support and compatibility for various sensors.</li><li><strong>Vehicles Chassis</strong>: Enable vehicle chassis control and debugging, improving adaptation capabilities.</li></ul><h4 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h4><ul><li><strong>Aconf Configuration Management</strong>: Provide a configuration management tool for flexible module configuration loading.</li><li><strong>Cviz Data Visualization</strong>: Support real-time visualization of key data in the autonomous driving system.</li><li><strong>DBC_tool Vehicle Chassis Adaptation</strong>: Optimize the vehicle chassis adaptation process and improve usability.</li><li><strong>Chassis Debugging Tool</strong>: Support debugging and performance optimization for chassis systems.</li></ul><hr><h2 id="wheel-app-version-release-plan" tabindex="-1">Wheel.App Version Release Plan <a class="header-anchor" href="#wheel-app-version-release-plan" aria-label="Permalink to &quot;Wheel.App Version Release Plan&quot;">​</a></h2><h3 id="version-2-28" tabindex="-1">Version 2.28 <a class="header-anchor" href="#version-2-28" aria-label="Permalink to &quot;Version 2.28&quot;">​</a></h3><h4 id="features-1" tabindex="-1">Features <a class="header-anchor" href="#features-1" aria-label="Permalink to &quot;Features&quot;">​</a></h4><ul><li><strong>Localization</strong>: Enable basic localization capabilities.</li><li><strong>Perception</strong>: Build the foundation of the perception module.</li><li><strong>Prediction</strong>: Support basic behavior prediction for dynamic objects.</li><li><strong>Planning</strong>: Implement initial path planning functionality.</li><li><strong>Control</strong>: Provide vehicle control capabilities.</li></ul><h4 id="tools-1" tabindex="-1">Tools <a class="header-anchor" href="#tools-1" aria-label="Permalink to &quot;Tools&quot;">​</a></h4><ul><li><strong>Sensor Calibration</strong>: Offer tools for sensor initialization and calibration.</li><li><strong>Sensor Time Synchronization</strong>: Resolve synchronization issues across multiple sensors.</li><li><strong>Vehicle Dynamics Calibration</strong>: Support calibration of vehicle dynamics-related parameters.</li><li><strong>Carla Integration</strong>: Enable integration with the Carla simulator through a bridging tool.</li></ul><h3 id="version-6-30" tabindex="-1">Version 6.30 <a class="header-anchor" href="#version-6-30" aria-label="Permalink to &quot;Version 6.30&quot;">​</a></h3><h4 id="features-2" tabindex="-1">Features <a class="header-anchor" href="#features-2" aria-label="Permalink to &quot;Features&quot;">​</a></h4><ul><li><strong>Middleware - Performance Optimization</strong>: Optimize the runtime performance of middleware modules.</li><li><strong>Hardware Adaptation</strong>: <ul><li>Support Horizon J6 hardware platform.</li><li>Enable NX5 hardware adaptation capabilities.</li></ul></li><li><strong>Localization</strong>: <ul><li>Enhance localization module performance with indoor localization support.</li><li>Implement multi-sensor fusion localization functionality.</li></ul></li><li><strong>Perception</strong>: <ul><li>Optimize perception module performance.</li><li>Implement semantic segmentation capabilities.</li><li>Establish a robust development process.</li></ul></li><li><strong>Prediction</strong>: Improve behavior prediction capabilities for dynamic environments.</li><li><strong>Planning</strong>: <ul><li>Provide planning capabilities independent of high-definition maps.</li><li>Introduce decision-making based on path behavior trees.</li></ul></li><li><strong>Control</strong>: Continuously optimize the vehicle control system.</li></ul><h4 id="operations" tabindex="-1">Operations <a class="header-anchor" href="#operations" aria-label="Permalink to &quot;Operations&quot;">​</a></h4><ul><li><strong>Functional Safety</strong>: Ensure the system&#39;s functional safety.</li><li><strong>Dispatch System</strong>: Implement a dispatch system with status monitoring and task scheduling capabilities.</li><li><strong>Remote Driving</strong>: Enable remote vehicle control via advanced instructions.</li></ul><h4 id="tools-2" tabindex="-1">Tools <a class="header-anchor" href="#tools-2" aria-label="Permalink to &quot;Tools&quot;">​</a></h4><ul><li><strong>Vehicle Dynamics Modeling</strong>: Support the construction of dynamic models based on vehicle parameters.</li></ul><hr><h2 id="overview-table" tabindex="-1">Overview Table <a class="header-anchor" href="#overview-table" aria-label="Permalink to &quot;Overview Table&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>Version</strong></th><th><strong>Features</strong></th><th><strong>Tools</strong></th><th><strong>Other Modules</strong></th></tr></thead><tbody><tr><td><strong>Wheel.OS 12.31</strong></td><td>Core Middleware, Common_msgs, Drivers, Vehicles</td><td>Aconf, Cviz, DBC_tool, Chassis Debugging Tool</td><td>None</td></tr><tr><td><strong>Wheel.App 2.28</strong></td><td>Localization, Perception, Prediction, Planning, Control</td><td>Sensor Calibration, Time Sync, Dynamics Calibration, Carla Bridge</td><td>None</td></tr><tr><td><strong>Wheel.App 6.30</strong></td><td>Middleware Optimization, Hardware Adaptation, Localization Enhancement, Perception Optimization, Prediction, Planning, Control</td><td>Vehicle Dynamics Modeling</td><td>Functional Safety, Dispatch System, Remote Driving</td></tr></tbody></table><hr><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><ul><li>Features in each version are incrementally prioritized to ensure system stability and performance optimization.</li><li>Tool modules will be iteratively updated based on the feature requirements of each version.</li><li>Operations modules will be progressively refined in future versions to ensure system safety and operational management capabilities.</li></ul>',27)])])}const p=i(n,[["render",r]]);export{m as __pageData,p as default};
